harness:
extends SceneTree
class CameraInput:
	extends RefCounted
	var dist := 69.9
	var focus_pos := Vector3.ZERO
class WorldInput:
	extends RefCounted
	var cam = CameraInput.new()
	func ground_y(_p: Vector3) -> float: return 0.0
class AirInput:
	extends RefCounted
	var atmo = {"sun":null}
	var _flip_frame := -1
var output := "/workspace/captures/qa302/before"
func _initialize() -> void: call_deferred("capture")
func capture() -> void:
	for arg in OS.get_cmdline_user_args():
		if arg.begins_with("--output="): output = arg.get_slice("=",1)
	DirAccess.make_dir_recursive_absolute(output)
	var scene := Node3D.new()
	root.add_child(scene)
	var sun := DirectionalLight3D.new()
	scene.add_child(sun)
	sun.global_transform = Transform3D(Basis.looking_at(-Vector3(0.35,0.8,0.45).normalized(),Vector3.UP),Vector3.ZERO)
	var world := WorldInput.new()
	if "--offset-phase" in OS.get_cmdline_user_args(): world.cam.focus_pos = Vector3(1.5,0.0,-3.0)
	var air := AirInput.new()
	air.atmo.sun = sun
	var shadow = load("/workspace/captures/qa302/inert-map.gd").new()
	scene.add_child(shadow)
	var supported := RenderingServer.get_current_rendering_method() != "gl_compatibility"
	if supported: shadow.setup(world,air)
	var plane := MeshInstance3D.new()
	var mesh := PlaneMesh.new()
	mesh.size = Vector2(40,40)
	plane.mesh = mesh
	var material := ShaderMaterial.new()
	var shader := Shader.new()
	shader.code = "shader_type spatial; render_mode unshaded;\n" + shadow.PATTERN + "\nvarying vec3 p; void vertex(){ p=(MODEL_MATRIX*vec4(VERTEX,1.0)).xyz; } void fragment(){ ALBEDO=vec3(0.42,0.46,0.39)*(0.25+0.75*smoke_sun(p)); }"
	material.shader = shader
	plane.material_override = material
	scene.add_child(plane)
	var camera := Camera3D.new()
	camera.projection = Camera3D.PROJECTION_ORTHOGONAL
	camera.size = 24.0
	camera.position = Vector3(0,30,0.01)
	scene.add_child(camera)
	camera.look_at(Vector3.ZERO,Vector3.FORWARD)
	camera.current = true
	for i in 24:
		if supported: shadow.tick(0.0)
		await process_frame
		await RenderingServer.frame_post_draw
	var values := [69.9,70.0,70.1,179.9,180.0,180.1]
	var records := []
	for d in values:
		world.cam.dist = d
		for i in 3:
			if supported: shadow.tick(0.0)
			await process_frame
			await RenderingServer.frame_post_draw
		root.get_texture().get_image().save_png(output + "/distance-%.1f.png" % d)
		records.append({"distance":d,"span":shadow._span,"peak":shadow.buf[8] if supported else 0.0})
	for frame in 120:
		var phase := frame % 60
		var threshold := 70.0 if frame < 60 else 180.0
		world.cam.dist = threshold + 5.0 * sin(TAU * (phase / 60.0 - 0.25))
		if supported: shadow.tick(0.0)
		await process_frame
		await RenderingServer.frame_post_draw
		root.get_texture().get_image().save_png(output + "/%04d.png" % frame)
	FileAccess.open(output+"/capture.json",FileAccess.WRITE).store_string(JSON.stringify({"source":"22b8f94e80b7c352ec13c19d32891c553d0c4866","renderer":RenderingServer.get_current_rendering_method(),"records":records,"fps":30,"frames":120,"fixture":"Inert fixed Gaussian map input and fixed receiver/camera. Only virtual camera distance changes. No emitters, combat, smoke simulation or altered art."},"\t"))
	print("INERT_SHADOW_COMPLETE ",records)
	quit()

